describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects non-positive upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 0, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects negative costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1000, costCents: -1 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1.5, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 100 }],
            -5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 2000, costCents: 700 },
      { upToGrams: 5000, costCents: 1200 },
    ]);

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents(emptyLines, 5000)).toBe(0);
    });

    it("returns 0 when weight is 0 (no weightGrams on products)", () => {
      const noWeight: CartLine[] = [
        { product: { id: "x", name: "X", unitPriceCents: 100 }, quantity: 3 },
      ];
      expect(calc.computeShippingCents(noWeight, 300)).toBe(0);
    });

    it("selects first bracket when weight is within it", () => {
      const lines = [makeLine("a", 200, 1)]; // 200g
      expect(calc.computeShippingCents(lines, 1000)).toBe(300);
    });

    it("selects bracket at exact boundary", () => {
      const lines = [makeLine("a", 500, 1)]; // exactly 500g
      expect(calc.computeShippingCents(lines, 1000)).toBe(300);
    });

    it("selects next bracket just above boundary", () => {
      const lines = [makeLine("a", 501, 1)]; // 501g
      expect(calc.computeShippingCents(lines, 1000)).toBe(700);
    });

    it("selects highest bracket for weight at its boundary", () => {
      const lines = [makeLine("a", 5000, 1)]; // exactly 5000g
      expect(calc.computeShippingCents(lines, 1000)).toBe(1200);
    });

    it("uses heaviest bracket cost when weight exceeds all brackets (no overflow)", () => {
      const lines = [makeLine("a", 6000, 1)]; // 6000g, beyond all brackets
      expect(calc.computeShippingCents(lines, 1000)).toBe(1200);
    });

    it("uses overflowCostCents when specified and weight exceeds all brackets", () => {
      const withOverflow = new WeightBasedShippingCalculator(
        [
          { upToGrams: 500, costCents: 300 },
          { upToGrams: 2000, costCents: 700 },
        ],
        1500,
      );
      const lines = [makeLine("a", 3000, 1)];
      expect(withOverflow.computeShippingCents(lines, 1000)).toBe(1500);
    });

    it("sorts brackets regardless of input order", () => {
      const unsorted = new WeightBasedShippingCalculator([
        { upToGrams: 2000, costCents: 700 },
        { upToGrams: 500, costCents: 300 },
      ]);
      const lines = [makeLine("a", 400, 1)]; // 400g → first bracket
      expect(unsorted.computeShippingCents(lines, 1000)).toBe(300);
    });

    it("accounts for quantity when computing weight", () => {
      // 3 × 400g = 1200g → second bracket (up to 2000g)
      const lines = [makeLine("a", 400, 3)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(700);
    });
  });
});

