import { describe, it, expect, vi, beforeEach } from "vitest";
import { Cart } from "../src/cart.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { Product, CartLine } from "../src/product.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import { InventoryError } from "../src/inventory.ts";

// ── Helpers ───────────────────────────────────────────────
const productA: Product = { id: "a", name: "Alpha", unitPriceCents: 1000 };
const productB: Product = {
  id: "b",
  name: "Beta",
  unitPriceCents: 2000,
  weightGrams: 500,
};

function makeDiscountPolicy(
  fn: (subtotal: number) => number,
): DiscountPolicy {
  return { computeDiscountCents: fn };
}

function makeTaxCalculator(
  fn: (taxable: number, region: string) => number,
): TaxCalculator {
  return { computeTaxCents: fn };
}

function makeShippingCalculator(
  fn: (lines: readonly CartLine[], subtotal: number) => number,
): ShippingCalculator {
  return { computeShippingCents: fn };
}

// ── Cart line management ──────────────────────────────────
describe("Cart line management", () => {
  let cart: Cart;

  beforeEach(() => {
    cart = new Cart();
  });

  it("starts empty with itemCount 0", () => {
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toEqual([]);
  });

  it("adds a product", () => {
    cart.add(productA, 3);
    expect(cart.itemCount).toBe(3);
    const snap = cart.snapshot();
    expect(snap).toHaveLength(1);
    expect(snap[0].product.id).toBe("a");
    expect(snap[0].quantity).toBe(3);
  });

  it("merges quantities when adding same product twice", () => {
    cart.add(productA, 2);
    cart.add(productA, 3);
    expect(cart.itemCount).toBe(5);
    expect(cart.snapshot()).toHaveLength(1);
    expect(cart.snapshot()[0].quantity).toBe(5);
  });

  it("rejects non-positive quantity on add", () => {
    expect(() => cart.add(productA, 0)).toThrow(RangeError);
    expect(() => cart.add(productA, -1)).toThrow(RangeError);
  });

  it("rejects non-integer quantity on add", () => {
    expect(() => cart.add(productA, 1.5)).toThrow(RangeError);
  });

  it("rejects negative unitPriceCents on add", () => {
    const bad: Product = { id: "bad", name: "Bad", unitPriceCents: -1 };
    expect(() => cart.add(bad, 1)).toThrow(RangeError);
  });

  it("removes a product and returns true", () => {
    cart.add(productA, 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("returns false when removing unknown product", () => {
    expect(cart.remove("unknown")).toBe(false);
  });

  it("updates quantity", () => {
    cart.add(productA, 3);
    cart.updateQuantity("a", 7);
    expect(cart.itemCount).toBe(7);
  });

  it("removes line when quantity updated to 0", () => {
    cart.add(productA, 3);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toHaveLength(0);
  });

  it("throws when updating unknown product", () => {
    expect(() => cart.updateQuantity("unknown", 5)).toThrow(
      "Product unknown is not in the cart",
    );
  });

  it("rejects negative quantity on updateQuantity", () => {
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("rejects non-integer quantity on updateQuantity", () => {
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
  });

  it("clears all lines", () => {
    cart.add(productA, 2);
    cart.add(productB, 3);
    cart.clear();
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toEqual([]);
  });

  it("snapshot returns a deep copy", () => {
    cart.add(productA, 1);
    const snap = cart.snapshot();
    snap[0].quantity = 999;
    snap[0].product.unitPriceCents = 0;
    // Original cart should be unaffected
    expect(cart.snapshot()[0].quantity).toBe(1);
    expect(cart.snapshot()[0].product.unitPriceCents).toBe(1000);
  });
});

// ── Cart.totals() pricing pipeline ────────────────────────
describe("Cart.totals() pricing pipeline", () => {
  it("returns all-zero totals for an empty cart", () => {
    const cart = new Cart();
    const t = cart.totals();
    expect(t.subtotalCents).toBe(0);
    expect(t.discountCents).toBe(0);
    expect(t.taxCents).toBe(0);
    expect(t.shippingCents).toBe(0);
    expect(t.totalCents).toBe(0);
  });

  it("computes subtotal as sum of unitPriceCents × quantity", () => {
    const cart = new Cart();
    cart.add(productA, 2); // 2000
    cart.add(productB, 1); // 2000
    expect(cart.totals().subtotalCents).toBe(4000);
  });

  it("applies discount, then tax on discounted subtotal, then shipping", () => {
    const discount = makeDiscountPolicy(() => 500); // flat 500 off
    const tax = makeTaxCalculator((taxable) => Math.floor(taxable * 0.1));
    const shipping = makeShippingCalculator(() => 300);

    const cart = new Cart({
      discountPolicy: discount,
      taxCalculator: tax,
      shippingCalculator: shipping,
    });
    cart.add(productA, 3); // subtotal = 3000

    const t = cart.totals();
    expect(t.subtotalCents).toBe(3000);
    expect(t.discountCents).toBe(500);
    // tax on (3000 - 500) = 2500 at 10% = 250
    expect(t.taxCents).toBe(250);
    expect(t.shippingCents).toBe(300);
    // total = 2500 + 250 + 300 = 3050
    expect(t.totalCents).toBe(3050);
  });

  it("clamps discount to [0, subtotal]", () => {
    // Policy returns more than subtotal
    const discount = makeDiscountPolicy(() => 99999);
    const cart = new Cart({ discountPolicy: discount });
    cart.add(productA, 1); // subtotal = 1000
    expect(cart.totals().discountCents).toBe(1000);
    expect(cart.totals().totalCents).toBe(0);
  });

  it("clamps negative discount to 0", () => {
    const discount = makeDiscountPolicy(() => -100);
    const cart = new Cart({ discountPolicy: discount });
    cart.add(productA, 1);
    expect(cart.totals().discountCents).toBe(0);
  });

  it("clamps negative tax to 0", () => {
    const tax = makeTaxCalculator(() => -50);
    const cart = new Cart({ taxCalculator: tax });
    cart.add(productA, 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const shipping = makeShippingCalculator(() => -10);
    const cart = new Cart({ shippingCalculator: shipping });
    cart.add(productA, 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("uses defaults (no discount, no tax, free shipping) without config", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(0);
    expect(t.taxCents).toBe(0);
    expect(t.shippingCents).toBe(0);
    expect(t.totalCents).toBe(1000);
  });

  it("passes region to tax calculator", () => {
    const taxFn = vi.fn().mockReturnValue(100);
    const tax = makeTaxCalculator(taxFn);
    const cart = new Cart({ taxCalculator: tax, region: "FR" });
    cart.add(productA, 1);
    cart.totals();
    expect(taxFn).toHaveBeenCalledWith(1000, "FR");
  });

  it("passes lines and discounted subtotal to shipping calculator", () => {
    const shippingFn = vi.fn().mockReturnValue(500);
    const discount = makeDiscountPolicy(() => 200);
    const cart = new Cart({
      discountPolicy: discount,
      shippingCalculator: makeShippingCalculator(shippingFn),
    });
    cart.add(productA, 1); // subtotal 1000, discounted 800
    cart.totals();
    expect(shippingFn).toHaveBeenCalledWith(
      expect.any(Array),
      800, // discounted subtotal
    );
  });
});

// ── Cart.checkout() ───────────────────────────────────────
describe("Cart.checkout()", () => {
  it("returns totals and lines without collaborators", async () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.lines).toHaveLength(1);
    expect(result.lines[0].quantity).toBe(2);
  });

  it("refreshes prices via priceFetcher before computing totals", async () => {
    const cart = new Cart();
    cart.add(productA, 1); // original price 1000

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };

    const result = await cart.checkout({ priceFetcher });
    expect(result.totals.subtotalCents).toBe(1500);
    expect(result.lines[0].product.unitPriceCents).toBe(1500);
    expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
  });

  it("checks inventory and proceeds when available", async () => {
    const cart = new Cart();
    cart.add(productA, 2);

    const inventoryChecker: InventoryChecker = {
      check: vi
        .fn()
        .mockResolvedValue({ available: true, availableQuantity: 10 }),
    };

    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
    expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
  });

  it("throws InventoryError when product is unavailable", async () => {
    const cart = new Cart();
    cart.add(productA, 5);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        availableQuantity: 2,
        reason: "low stock",
      }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("a");
      expect(invErr.requested).toBe(5);
      expect(invErr.available).toBe(2);
      expect(invErr.message).toBe("low stock");
    }
  });

  it("throws InventoryError on partial-stock denial (available: true but quantity insufficient)", async () => {
    const cart = new Cart();
    cart.add(productA, 10);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("a");
      expect(invErr.requested).toBe(10);
      expect(invErr.available).toBe(3);
    }
  });

  it("uses asyncTaxProvider for tax computation", async () => {
    const taxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.08),
    };

    const cart = new Cart({ region: "US-TX" });
    cart.add(productA, 1); // subtotal 1000

    const result = await cart.checkout({ asyncTaxProvider: taxProvider });
    // 8% of 1000 = 80
    expect(result.totals.taxCents).toBe(80);
    expect(taxProvider.getRate).toHaveBeenCalledWith("US-TX");
  });

  it("composes discount + asyncTax + shipping correctly", async () => {
    const discount = makeDiscountPolicy(() => 200);
    const shipping = makeShippingCalculator(() => 400);
    const taxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.10),
    };

    const cart = new Cart({
      discountPolicy: discount,
      shippingCalculator: shipping,
    });
    cart.add(productA, 2); // subtotal 2000

    const result = await cart.checkout({ asyncTaxProvider: taxProvider });
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.totals.discountCents).toBe(200);
    // tax on (2000 - 200) = 1800 at 10% = 180
    expect(result.totals.taxCents).toBe(180);
    expect(result.totals.shippingCents).toBe(400);
    // total = 1800 + 180 + 400 = 2380
    expect(result.totals.totalCents).toBe(2380);
  });

  it("propagates priceFetcher rejection", async () => {
    const cart = new Cart();
    cart.add(productA, 1);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi
        .fn()
        .mockRejectedValue(new Error("price service down")),
    };

    await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
      "price service down",
    );
  });

  it("propagates asyncTaxProvider rejection", async () => {
    const taxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };

    const cart = new Cart();
    cart.add(productA, 1);

    await expect(
      cart.checkout({ asyncTaxProvider: taxProvider }),
    ).rejects.toThrow("tax service down");
  });

  it("uses default InventoryError message when no reason provided", async () => {
    const cart = new Cart();
    cart.add(productA, 5);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
      }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.message).toContain("insufficient stock");
      expect(invErr.available).toBe(0);
    }
  });

  it("checkout with all collaborators: price refresh → inventory → async tax", async () => {
    const cart = new Cart({
      discountPolicy: makeDiscountPolicy(() => 100),
      shippingCalculator: makeShippingCalculator(() => 250),
      region: "US",
    });
    cart.add(productA, 2);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1200),
    };
    const inventoryChecker: InventoryChecker = {
      check: vi
        .fn()
        .mockResolvedValue({ available: true, availableQuantity: 50 }),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.05),
    };

    const result = await cart.checkout({
      priceFetcher,
      inventoryChecker,
      asyncTaxProvider,
    });

    // refreshed price: 1200 × 2 = 2400
    expect(result.totals.subtotalCents).toBe(2400);
    expect(result.totals.discountCents).toBe(100);
    // tax on (2400 - 100) = 2300 at 5% = 115
    expect(result.totals.taxCents).toBe(115);
    expect(result.totals.shippingCents).toBe(250);
    // total = 2300 + 115 + 250 = 2665
    expect(result.totals.totalCents).toBe(2665);

    expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
    expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US");
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([
    [0, 0],
    [1000, 0],
    [-500, 0],
    [999999, 0],
  ])("computeDiscountCents(%i) returns %i", (subtotal, expected) => {
    expect(policy.computeDiscountCents(subtotal)).toBe(expected);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([
      [-1, "percent must be between 0 and 100"],
      [101, "percent must be between 0 and 100"],
      [NaN, "percent must be between 0 and 100"],
      [Infinity, "percent must be between 0 and 100"],
    ])("rejects invalid percent %s", (percent, msg) => {
      expect(() => new PercentageDiscountPolicy(percent)).toThrow(RangeError);
    });

    it("accepts boundary values 0 and 100", () => {
      expect(() => new PercentageDiscountPolicy(0)).not.toThrow();
      expect(() => new PercentageDiscountPolicy(100)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it.each([
      [10, 1000, 100],
      [50, 1000, 500],
      [100, 1000, 1000],
      [0, 1000, 0],
      [33, 10000, 3300],
      // Rounding: 15% of 999 = 149.85 → floored to 149
      [15, 999, 149],
      [10, 1, 0], // 10% of 1 cent = 0.1 → floored to 0
    ])(
      "%i%% of %i cents = %i",
      (percent, subtotal, expected) => {
        const policy = new PercentageDiscountPolicy(percent);
        expect(policy.computeDiscountCents(subtotal)).toBe(expected);
      },
    );

    it("returns 0 for zero subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(-1000)).toBe(0);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects negative amount", () => {
      expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
    });

    it("rejects non-integer amount", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

    it("accepts zero", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns the fixed amount when subtotal exceeds it", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(1000)).toBe(500);
    });

    it("caps at subtotal when fixed amount exceeds subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(2000);
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("returns exact subtotal when amounts are equal", () => {
      const policy = new FixedAmountDiscountPolicy(1000);
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums independent policy results against original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 10000 = 1000
          new FixedAmountDiscountPolicy(500), // 500
        ],
        "sum",
      );
      expect(composite.computeDiscountCents(10000)).toBe(1500);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(500)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(500)],
        "sum",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("clamps negative child results to zero before summing", () => {
      // NoDiscountPolicy returns 0, so this just confirms no negative contribution
      const composite = new CompositeDiscountPolicy(
        [new NoDiscountPolicy(), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      expect(composite.computeDiscountCents(1000)).toBe(200);
    });

    it("defaults to sum mode when mode not specified", () => {
      const composite = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(500),
      ]);
      // sum mode: both see 10000 → 1000 + 500 = 1500
      expect(composite.computeDiscountCents(10000)).toBe(1500);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially to remaining subtotal", () => {
      // 10% of 10000 = 1000, then fixed 500 of remaining 9000 = 500
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(500)],
        "chain",
      );
      expect(composite.computeDiscountCents(10000)).toBe(1500);
    });

    it("ordering matters in chain mode", () => {
      // fixed 500 of 10000 first, then 10% of remaining 9500 = 950
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(500), new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(composite.computeDiscountCents(10000)).toBe(1450);
    });

    it("chain caps each step at remaining subtotal", () => {
      // Two large fixed amounts: 8000 off 10000 = remaining 2000, then 8000 caps to 2000
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(8000),
          new FixedAmountDiscountPolicy(8000),
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(10000)).toBe(10000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });
});

